def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    history: list[tuple] = []
    rejected: list[int] = []

    def parse_amount(token: str):
        if not token or not (token.isascii() and token.isdigit()):
            return None
        return int(token)

    for i, op in enumerate(ops):
        parts = op.split(" ")
        if not parts or any(p == "" for p in parts):
            rejected.append(i)
            continue

        verb = parts[0]
        n_parts = len(parts)

        if verb == "open" and n_parts == 3:
            acc = parts[1]
            amount = parse_amount(parts[2])
            if amount is not None and acc not in balances:
                balances[acc] = amount
                history.append(("open", acc))
                continue
        elif verb == "deposit" and n_parts == 3:
            acc = parts[1]
            amount = parse_amount(parts[2])
            if amount is not None and amount > 0 and acc in balances:
                balances[acc] += amount
                history.append(("deposit", acc, amount))
                continue
        elif verb == "withdraw" and n_parts == 3:
            acc = parts[1]
            amount = parse_amount(parts[2])
            if (
                amount is not None
                and amount > 0
                and acc in balances
                and acc not in frozen
                and balances[acc] >= amount
            ):
                balances[acc] -= amount
                history.append(("withdraw", acc, amount))
                continue
        elif verb == "transfer" and n_parts == 4:
            src, dst = parts[1], parts[2]
            amount = parse_amount(parts[3])
            if (
                amount is not None
                and amount > 0
                and src != dst
                and src in balances
                and dst in balances
                and src not in frozen
                and balances[src] >= amount
            ):
                balances[src] -= amount
                balances[dst] += amount
                history.append(("transfer", src, dst, amount))
                continue
        elif verb == "freeze" and n_parts == 2:
            acc = parts[1]
            if acc in balances and acc not in frozen:
                frozen.add(acc)
                history.append(("freeze", acc))
                continue
        elif verb == "unfreeze" and n_parts == 2:
            acc = parts[1]
            if acc in balances and acc in frozen:
                frozen.remove(acc)
                history.append(("unfreeze", acc))
                continue
        elif verb == "undo" and n_parts == 1:
            if history:
                entry = history.pop()
                kind = entry[0]
                if kind == "open":
                    del balances[entry[1]]
                elif kind == "deposit":
                    balances[entry[1]] -= entry[2]
                elif kind == "withdraw":
                    balances[entry[1]] += entry[2]
                elif kind == "transfer":
                    balances[entry[1]] += entry[3]
                    balances[entry[2]] -= entry[3]
                elif kind == "freeze":
                    frozen.remove(entry[1])
                elif kind == "unfreeze":
                    frozen.add(entry[1])
                continue

        rejected.append(i)

    return balances, rejected
